import java.io.File; import javax.sound.sampled.*; public class TestSeek { public static void main(String[] args) throws Exception { File dir = new File("C:/Users/HayasakaAi/Music"); File f = dir.listFiles()[0]; AudioInputStream in = AudioSystem.getAudioInputStream(f); AudioFormat baseFormat = in.getFormat(); AudioFormat decodedFormat = new AudioFormat(AudioFormat.Encoding.PCM_SIGNED, baseFormat.getSampleRate(), 16, baseFormat.getChannels(), baseFormat.getChannels() * 2, baseFormat.getSampleRate(), false); AudioInputStream din = AudioSystem.getAudioInputStream(decodedFormat, in); System.out.println("Trying to skip..."); long skipped = din.skip(1000000); System.out.println("Skipped: " + skipped); } }
